+    const __m128 oneMinusW = _mm_sub_ps(one, w);
+    return _mm_or_ps(_mm_and_ps(positive, oneMinusW), _mm_andnot_ps(pos"}, {"id": "3b9fd1eef6f24d23", "role": "T2", "commit": "2d8af76f9a7c72c903730e86dd42613c58da97ac", "transformations": {"files": ["src/candidate.cpp"], "retained": ["Added SSE2 polynomial approximations for log and exp to remove per-lane scalar transcendental calls on safe ranges.", "Retained the original arithmetic structure and supplied CND coefficients in the vector kernel.", "Fell back to the scalar serial routine for non-normal ratios, unsafe exponential ranges, unsupported builds, and vector tails.", "Kept threading, compiler flags, and the run entrypoint unchanged."]}, "mean_seconds": 0.0026624168454253494, "diff": "diff --git a/src/candidate.cpp b/src/candidate.cpp
